import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

// Generated export only: the project root remains the single source of truth.
const root = dirname(dirname(fileURLToPath(import.meta.url)));
const read = path => readFile(join(root, path), 'utf8');
const output = join(root, 'dist', 'inquiry-demo.html');
const sources = await Promise.all([
  'index.html', 'js/data.js', 'js/lily.js', 'js/inquiry-data.js', 'js/shared.js',
  'assets/lucide.min.js', 'assets/favicon.svg', 'css/design-tokens.css', 'css/base.css',
  'css/lily-secondary.css', 'css/responsive.css', 'css/inquiry-messaging.css',
  'css/inquiry-standalone.css'
].map(read));
const [index, data, lily, inquiryData, shared, icons, favicon, ...styles] = sources;

function extract(source, start, end, includeEnd = false) {
  const from = source.indexOf(start);
  const to = source.indexOf(end, from + start.length);
  if (from < 0 || to < 0) throw new Error(`Standalone source boundary changed: ${start}`);
  return source.slice(from, to + (includeEnd ? end.length : 0));
}
function escapeInline(source, tag) {
  return source.replace(new RegExp(`</${tag}`, 'gi'), `<\\/${tag}`);
}

const markup = extract(index,
  '<section class="lily-secondary inquiry-page"',
  '<section class="lily-secondary templates-page"'
).replace('aria-label="询盘消息" hidden>', 'aria-label="询盘消息">');
const toast = extract(index, '<div class="toast" id="toast"', '</div>', true);
const stageData = extract(lily, 'const customerDetailStages = [', '\n];', true);
const conversationData = extract(data, 'const inquiryDemoConversations = [', '\n];', true);
const companyData = extract(data, 'const inquiryCompanyProfiles = {', '\n};', true);
const workspace = extract(lily, 'function initInquiryWorkspace() {', '\ninitInquiryWorkspace();', true);
const embeddedIcons = icons.replace(/^\/\/[#@] sourceMappingURL=.*$/gm, '');
const scripts = [embeddedIcons, shared, stageData, conversationData, companyData, inquiryData, workspace, 'refreshIcons();'];
const css = styles.join('\n\n');
// Fail loudly if future changes introduce dependencies that need embedding.
if (/@import\b|url\(\s*['"]?(?!data:|#)/i.test(css)) {
  throw new Error('A stylesheet contains an external resource; embed it before exporting.');
}
if (/\b(?:src|href)\s*=\s*["'](?:assets|css|js)\//i.test(markup)) {
  throw new Error('Inquiry markup references a local asset; embed it before exporting.');
}

const html = `<!doctype html>
<!-- Generated by npm run build:inquiry. Edit root project sources, then rebuild. -->
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="color-scheme" content="light">
  <meta name="description" content="OntoZ 询盘消息独立演示：邮件、WhatsApp 与 WhatsApp 企业号">
  <title>OntoZ · 询盘消息 Demo</title>
  <link rel="icon" href="data:image/svg+xml;base64,${Buffer.from(favicon).toString('base64')}">
  <style>${escapeInline(css, 'style')}</style>
</head>
<body class="inquiry-standalone">
  <noscript>请启用 JavaScript 以使用询盘消息演示。</noscript>
  <main aria-label="询盘消息演示">${markup}</main>
  ${toast}
  ${scripts.map(source => `<script>${escapeInline(source, 'script')}</script>`).join('\n')}
</body>
</html>
`;
await mkdir(dirname(output), { recursive: true });
await writeFile(output, html);
console.log(`Built ${output} (${(Buffer.byteLength(html) / 1024).toFixed(0)} KB, self-contained HTML)`);
